	var a := Vector3(float(start[0]), float(start[1]), float(start[2]))
	var b := Vector3(float(end[0]), float(end[1]), float(end[2]))
	var segment := b - a
	var length_m := segment.length()
	if length_m <= 0.0:
		return 0.0
	var density := float(test_input.get("density_per_m", 0.0))
	var falloff := float(test_input.get("height_falloff_per_m", 0.0))
	var reference := float(test_input.get("reference_height_m", 0.0))
	var y0 := a.y - reference
	var dy := b.y - a.y
