	environment.fog_light_color = Color(0.65, 0.72, 0.78)
	environment.fog_density = 0.01
	environment.fog_height = float(test_input.get("reference_height_m", 0.0))
	environment.fog_height_density = float(test_input.get("height_falloff_per_m", 0.15))
	# Do not veil the preserved sky; geometry still receives the atmospheric fog.
	environment.fog_sky_affect = 0.0 if bool(test_input.get("preserve_sky", true)) else 1.0
