	# Integrate from the denser endpoint; avoids subtracting two large
	# exponentials and guarantees identical results for reversed segments.
	var factor: float
	if x < 0.001:
		factor = 1.0 - x * 0.5 + x * x / 6.0 - x * x * x / 24.0
	else:
		factor = (1.0 - exp(-x)) / x
	return density * length_m * exp(maxf(e0, e1)) * factor

