func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	_configure_scene_fog()
	_install_screen_fog()
	_sample_cache = _compute_samples()

func _configure_scene_fog() -> void:
	# The screen pass performs the finite segment integration; disable the
	# host's approximate global fog so sky/clouds remain exactly as authored.
	if scene_root == null:
		return
	var world := scene_root.get_node_or_null("WorldEnvironment") as WorldEnvironment
	if world == null or world.environment == null:
		return
	var env: Environment = world.environment.duplicate()
	env.fog_enabled = false
	env.volumetric_fog_enabled = false
	world.environment = env

func _install_screen_fog() -> void:
	if scene_root == null or scene_root.get_node_or_null("HeightFogOverlay") != null:
		return
	var overlay := MeshInstance3D.new()
	overlay.name = "HeightFogOverlay"
	overlay.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	overlay.extra_cull_margin = 100000.0
	overlay.render_priority = 100
	var quad := QuadMesh.new()
	quad.size = Vector2(2.0, 2.0)
	overlay.mesh = quad
	var material := ShaderMaterial.new()
	material.shader = load("res://effect/height_fog.gdshader")
	material.set_shader_parameter("density_per_m", float(test_input.get("density_per_m", 0.01)))
	material.set_shader_parameter("height_falloff_per_m", float(test_input.get("height_falloff_per_m", 0.15)))
	material.set_shader_parameter("reference_height_m", float(test_input.get("reference_height_m", 0.0)))
	var fog: Array = test_input.get("fog_color_linear", [0.65, 0.72, 0.78])
	material.set_shader_parameter("fog_color_linear", Color(float(fog[0]), float(fog[1]), float(fog[2]), 1.0))
	overlay.material_override = material
	scene_root.add_child.call_deferred(overlay)

func step(_dt: float) -> void:
	pass

func _compute_optical_depth(start: Array, end: Array) -> float:
	var dx := float(end[0]) - float(start[0])
	var dy := float(end[1]) - float(start[1])
	var dz := float(end[2]) - float(start[2])
	var length_m := sqrt(dx * dx + dy * dy + dz * dz)
	var density := maxf(0.0, float(test_input.get("density_per_m", 0.0)))
	if length_m == 0.0 or density == 0.0:
		return 0.0
	var falloff := float(test_input.get("height_falloff_per_m", 0.0))
	var reference := float(test_input.get("reference_height_m", 0.0))
	var e0 := -falloff * (float(start[1]) - reference)
	var e1 := -falloff * (float(end[1]) - reference)
	var x := absf(e1 - e0)
	var factor: float
	if x < 0.001:
		factor = 1.0 - x * 0.5 + x * x / 6.0 - x * x * x / 24.0
	else:
		factor = (1.0 - exp(-x)) / x
	return density * length_m * exp(maxf(e0, e1)) * factor

func _compute_samples() -> Dictionary:
	var rays: Array = []
	var depths: Array = []
	var weights: Array = []
	var colors: Array = []
	var fog: Array = test_input.get("fog_color_linear", [0.0, 0.0, 0.0])
	for ray: Dictionary in test_input.get("rays", []):
		var depth := _compute_optical_depth(ray["start"], ray["end"])
		var transmittance := exp(-depth)
		var opacity := 1.0 - transmittance
		var background: Array = ray["background_linear"]
		var color: Array = []
		for channel in 3:
			color.append(transmittance * float(background[channel]) + opacity * float(fog[channel]))
