func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	_configure_scene_fog()
	_sample_cache = _compute_samples()

func _configure_scene_fog() -> void:
	# The host deliberately disables its original fog. Re-enable only the
	# environment fog, leaving its sky/cloud and Canvas UI untouched.
	if scene_root == null:
		return
	var environment_node := scene_root.get_node_or_null("WorldEnvironment") as WorldEnvironment
	if environment_node == null or environment_node.environment == null:
		return
	var environment: Environment = environment_node.environment.duplicate()
	environment.fog_enabled = true
	environment.fog_light_color = Color(0.65, 0.72, 0.78)
	environment.fog_density = 0.01
	environment.fog_height = float(test_input.get("reference_height_m", 0.0))
	environment.fog_height_density = float(test_input.get("height_falloff_per_m", 0.15))
	# Do not veil the preserved sky; geometry still receives the atmospheric fog.
	environment.fog_sky_affect = 0.0 if bool(test_input.get("preserve_sky", true)) else 1.0
	environment_node.environment = environment

func step(_dt: float) -> void:
	# The fixed rays are static; scene animation is advanced by the host.
	pass

func _compute_optical_depth(start: Array, end: Array) -> float:
	var a := Vector3(float(start[0]), float(start[1]), float(start[2]))
	var b := Vector3(float(end[0]), float(end[1]), float(end[2]))
	var segment := b - a
	var length_m := segment.length()
	if length_m <= 0.0:
		return 0.0
	var density := float(test_input.get("density_per_m", 0.0))
	var falloff := float(test_input.get("height_falloff_per_m", 0.0))
	var reference := float(test_input.get("reference_height_m", 0.0))
	var y0 := a.y - reference
	var dy := b.y - a.y
	var integral_factor: float
	if absf(falloff * dy) < 0.000001:
		integral_factor = 1.0
	else:
		# Integral from t=0..1 of exp(-falloff*dy*t), evaluated stably
		# enough for both upward and downward rays.
		integral_factor = -expm1(-falloff * dy) / (falloff * dy)
	return maxf(0.0, density * length_m * exp(-falloff * y0) * integral_factor)

func _compute_samples() -> Dictionary:
	var result: Array = []
	var fog: Array = test_input.get("fog_color_linear", [0.0, 0.0, 0.0])
	for ray_variant in test_input.get("rays", []):
		var ray: Dictionary = ray_variant
		var optical_depth := _compute_optical_depth(ray.get("start", [0,0,0]), ray.get("end", [0,0,0]))
		var transmittance := exp(-optical_depth)
		var opacity := 1.0 - transmittance
		var background: Array = ray.get("background_linear", [0.0, 0.0, 0.0])
		var color: Array = []
