	var b := Vector3(float(end[0]), float(end[1]), float(end[2]))
	var segment := b - a
	var length_m := segment.length()
	if length_m <= 0.0:
		return 0.0
	var density := float(test_input.get("density_per_m", 0.0))
	var falloff := float(test_input.get("height_falloff_per_m", 0.0))
