{"path":"effect/height_fog.gdshader","content":"shader_type spatial;
render_mode unshaded, fog_disabled, cull_disabled, depth_draw_never, depth_test_disabled, shadows_disabled;

uniform sampler2D scene_color : hint_screen_texture, repeat_disable, filter_nearest;
uniform sampler2D scene_depth : hint_depth_texture, repeat_disable, filter_nearest;
uniform float density_per_m = 0.01;
uniform float height_falloff_per_m = 0.15;
uniform float reference_height_m = 0.0;
// Already linear: deliberately no source_color conversion.
uniform vec3 fog_color_linear = vec3(0.65, 0.72, 0.78);

void vertex() {
	// Godot 4.6 reverse-Z near plane. Independent of mesh transform.
	POSITION = vec4(VERTEX.xy, 1.0, 1.0);
}

void fragment() {
	float depth = textureLod(scene_depth, SCREEN_UV, 0.0).r;
	// Clear depth has no finite visible surface; retain original sky/clouds.
	if (depth <= 0.0) {
		discard;
	}
	vec3 ndc = vec3(SCREEN_UV * 2.0 - 1.0, depth);
#if CURRENT_RENDERER == RENDERER_COMPATIBILITY
	ndc.z = depth * 2.0 - 1.0;
#endif
	vec4 view_h = INV_PROJECTION_MATRIX * vec4(ndc, 1.0);
	vec3 view_position = view_h.xyz / view_h.w;
	vec3 endpoint = (INV_VIEW_MATRIX * vec4(view_position, 1.0)).xyz;
	vec3 startpoint = INV_VIEW_MATRIX[3].xyz;
	float ray_length = length(endpoint - startpoint);
	float e0 = -height_falloff_per_m * (startpoint.y - reference_height_m);
	float e1 = -height_falloff_per_m * (endpoint.y - reference_height_m);
	float x = abs(e1 - e0);
	float factor;
	if (x < 0.001) {
		factor = 1.0 - 0.5*x + x*x/6.0 - x*x*x/24.0;
	} else {
		factor = (1.0 - exp(-x)) / x;
	}
	// Log domain prevents overflow at very low elevations. Clamping only
	// occurs after tau is large enough that T is visually indistinguishable from 0.
	float tau = 0.0;
	if (density_per_m > 0.0 && ray_length > 0.0) {
		float log_tau = log(density_per_m) + log(ray_length) + max(e0,e1) + log(factor);
		tau = exp(min(log_tau, log(80.0)));
	}
	float transmittance = exp(-tau);
	vec3 background = textureLod(scene_color, SCREEN_UV, 0.0).rgb;
	ALBEDO = transmittance * background + (1.0 - transmittance) * fog_color_linear;
	ALPHA = 1.0;
}
"}

{"path":"effect/main.gd","content":"extends Node
## Finite-ray exponential height fog and a screen-space scene pass.
var scene_root: Node
var test_input: Dictionary = {}
var _sample_cache: Dictionary = {}

func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	_configure_scene_fog()
	_install_screen_fog()
	_sample_cache = _compute_samples()

func _configure_scene_fog() -> void:
	# The screen pass performs the finite segment integration; disable the
	# host's approximate global fog so sky/clouds remain exactly as authored.
	if scene_root == null:
		return
	var world := scene_root.get_node_or_null("WorldEnvironment") as WorldEnvironment
	if world == null or world.environment == null:
		return
	var env: Environment = world.environment.duplicate()
	env.fog_enabled = false
	env.volumetric_fog_enabled = false
	world.environment = env

func _install_screen_fog() -> void:
	if scene_root == null or scene_root.get_node_or_null("HeightFogOverlay") != null:
		return
	var overlay := MeshInstance3D.new()
	overlay.name = "HeightFogOverlay"
	overlay.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	overlay.extra_cull_margin = 100000.0
	overlay.render_priority = 100
	var quad := QuadMesh.new()
	quad.size = Vector2(2.0, 2.0)
	overlay.mesh = quad
	var material := ShaderMaterial.new()
	material.shader = load("res://effect/height_fog.gdshader")
	material.set_shader_parameter("density_per_m", float(test_input.get("density_per_m", 0.01)))
	material.set_shader_parameter("height_falloff_per_m", float(test_input.get("height_falloff_per_m", 0.15)))
	material.set_shader_parameter("reference_height_m", float(test_input.get("reference_height_m", 0.0)))
	var fog: Array = test_input.get("fog_color_linear", [0.65, 0.72, 0.78])
	material.set_shader_parameter("fog_color_linear", Color(float(fog[0]), float(fog[1]), float(fog[2]), 1.0))
	overlay.material_override = material
	scene_root.add_child.call_deferred(overlay)

