		depths.append(depth)
		weights.append([transmittance, opacity])
		colors.append(color)
	return {"rays": rays, "optical_depth": depths,
		"transmittance_opacity": weights, "color_linear": colors}

func sample() -> Dictionary:
	return _sample_cache
"}

