	else:
		factor = (1.0 - exp(-x)) / x
	return density * length_m * exp(maxf(e0, e1)) * factor

func _compute_samples() -> Dictionary:
	var rays: Array = []
	var depths: Array = []
	var weights: Array = []
	var colors: Array = []
	var fog: Array = test_input["fog_color_linear"]
	for ray: Dictionary in test_input["rays"]:
